import enUS from './en-US.js';
import esMX from './es-MX.js';
import frCA from './fr-CA.js';

/**
 * DatePicker Locale Resources
 *
 * These JSON translation files can be imported by consumers who want to
 * integrate DatePicker translations into their own i18n setup.
 *
 * **Note:** The `*.storybook.json` files contain Storybook-only strings
 * and are NOT exported or included in the production bundle. They are
 * only used in component documentation.
 *
 * ## Usage Example
 *
 * ```typescript
 * import i18n from 'i18next';
 * import { initReactI18next } from 'react-i18next';
 * import {
 *   datePickerLocaleEnUS,
 *   datePickerLocaleEsMX,
 *   datePickerLocaleFrCA
 * } from '@walmart-dataventures/shared-components';
 *
 * i18n.use(initReactI18next).init({
 *   lng: 'en-US',
 *   fallbackLng: 'en-US',
 *   ns: ['DatePicker', 'shared'],
 *   resources: {
 *     'en-US': {
 *       DatePicker: datePickerLocaleEnUS,
 *       shared: { ... }
 *     },
 *     'es-MX': {
 *       DatePicker: datePickerLocaleEsMX,
 *       shared: { ... }
 *     },
 *     'fr-CA': {
 *       DatePicker: datePickerLocaleFrCA,
 *       shared: { ... }
 *     }
 *   }
 * });
 * ```
 *
 * ## Changing the Active Locale
 *
 * To change the locale at runtime, use i18next's `changeLanguage()` method:
 *
 * ```typescript
 * import { useTranslation } from 'react-i18next';
 *
 * function LanguageSwitcher() {
 *   const { i18n } = useTranslation();
 *   return (
 *     <button onClick={() => i18n.changeLanguage('es-MX')}>
 *       Switch to Spanish
 *     </button>
 *   );
 * }
 * ```
 *
 * DatePicker components will automatically use the active i18next locale.
 * You can also pass a `locale` prop to individual components to override
 * the global locale for that specific instance.
 */

var datePickerLocaleEnUS = enUS;
var datePickerLocaleEsMX = esMX;
var datePickerLocaleFrCA = frCA;

/**
 * All available locales as a map for programmatic access
 */
var datePickerLocales = {
  'en-US': enUS,
  'es-MX': esMX,
  'fr-CA': frCA
};

export { datePickerLocaleEnUS, datePickerLocaleEsMX, datePickerLocaleFrCA, datePickerLocales };
